import React, { createContext, useContext, useState, useEffect } from 'react';
import Keycloak from 'keycloak-js';

const AuthContext = createContext();

// Keycloak configuration
const keycloakConfig = {
  url: process.env.REACT_APP_KEYCLOAK_URL || 'http://localhost:8080',
  realm: process.env.REACT_APP_KEYCLOAK_REALM || 'medimesh',
  clientId: process.env.REACT_APP_KEYCLOAK_CLIENT_ID || 'medimesh-client'
};

export const AuthProvider = ({ children }) => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [keycloak, setKeycloak] = useState(null);
  const [token, setToken] = useState(null);

  useEffect(() => {
    const initKeycloak = async () => {
      try {
        const kc = new Keycloak(keycloakConfig);
        
        const authenticated = await kc.init({
          onLoad: 'check-sso',
          silentCheckSsoRedirectUri: window.location.origin + '/silent-check-sso.html',
          checkLoginIframe: false
        });

        setKeycloak(kc);

        if (authenticated) {
          setIsAuthenticated(true);
          setToken(kc.token);
          
          // Get user profile
          const profile = await kc.loadUserProfile();
          setUser({
            id: kc.subject,
            username: kc.tokenParsed.preferred_username,
            email: profile.email,
            firstName: profile.firstName,
            lastName: profile.lastName,
            roles: kc.tokenParsed.realm_access?.roles || [],
            fullName: `${profile.firstName} ${profile.lastName}`.trim()
          });

          // Set up token refresh
          kc.onTokenExpired = () => {
            kc.updateToken(30).then((refreshed) => {
              if (refreshed) {
                setToken(kc.token);
                console.log('Token refreshed');
              } else {
                console.log('Token still valid');
              }
            }).catch(() => {
              console.error('Failed to refresh token');
              logout();
            });
          };
        }
      } catch (error) {
        console.error('Keycloak initialization failed:', error);
        // For development, allow bypass if Keycloak is not available
        if (process.env.NODE_ENV === 'development') {
          setIsAuthenticated(true);
          setUser({
            id: 'dev-user',
            username: 'developer',
            email: 'developer@medimesh.com',
            firstName: 'Developer',
            lastName: 'User',
            roles: ['doctor', 'admin'],
            fullName: 'Developer User'
          });
          setToken('dev-token');
        }
      } finally {
        setLoading(false);
      }
    };

    initKeycloak();
  }, []);

  const login = () => {
    if (keycloak) {
      keycloak.login();
    } else if (process.env.NODE_ENV === 'development') {
      // Development mode login
      setIsAuthenticated(true);
      setUser({
        id: 'dev-user',
        username: 'developer',
        email: 'developer@medimesh.com',
        firstName: 'Developer',
        lastName: 'User',
        roles: ['doctor', 'admin'],
        fullName: 'Developer User'
      });
      setToken('dev-token');
    }
  };

  const logout = () => {
    if (keycloak) {
      keycloak.logout({
        redirectUri: window.location.origin
      });
    } else {
      // Development mode logout
      setIsAuthenticated(false);
      setUser(null);
      setToken(null);
    }
  };

  const hasRole = (role) => {
    return user?.roles?.includes(role) || false;
  };

  const hasAnyRole = (roles) => {
    return roles.some(role => hasRole(role));
  };

  const getAuthHeaders = () => {
    if (token) {
      return {
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json'
      };
    }
    return {
      'Content-Type': 'application/json'
    };
  };

  const value = {
    isAuthenticated,
    user,
    loading,
    token,
    keycloak,
    login,
    logout,
    hasRole,
    hasAnyRole,
    getAuthHeaders
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};
